      en: ["Built in the 19th century.", "Contains tombs of 4 kabakas.", "UNESCO tentative list since 2001.", "Area: 2 hectares.", "Height of main structure: 10 meters.", "Distance from Kampala: 15 km."],
      es: ["Construido en el siglo XIX.", "Contiene las tumbas de 4 Kabakas.", "Lista provisional de la UNESCO desde 2001.", "Superficie: 2 hectáreas.", "Altura de la estructura principal: 10 metros.", "Distancia desde Kampala: 15 km."],
