      fr: ["Construit au XIXe siècle.", "Contient les tombes de 4 Kabakas.", "Liste provisoire de l'UNESCO depuis 2001.", "Surface: 2 hectares.", "Hauteur de la structure principale: 10 mètres.", "Distance de Kampala: 15 km."],
