    image: "/poi-images/karambi-royal-tombs-history-v2.webp",
    description: {
      de: "Die Karambi-Königsgräber sind die Begräbnisstätte der Könige (Omukamas) von Toro und ein Ort von historischer Bedeutung.",
      hu: "A Karambi királyi sírok Toro királyainak (Omukama) temetkezési helye, történelmi jelentőségű helyszín.",
      ro: "Mormintele regale Karambi sunt locul de înmormântare al regilor (Omukama) din Toro și un sit de importanță istorică.",
      en: "The Karambi Royal Tombs are the burial site of the Kings (Omukamas) of Toro and a site of historical importance.",
      es: "Las Tumbas Reales de Karambi son el lugar de enterramiento de los reyes (Omukamas) de Toro y un lugar de importancia histórica.",
      pt: "Os Túmulos Reais de Karambi são o local de sepultamento dos reis (Omukamas) de Toro e um local de importância histórica.",
      fr: "Les tombeaux royaux de Karambi sont le lieu de sépulture des rois (Omukamas) du Toro et un lieu d'importance historique.",
    },
    facts: {
      de: ["Grabstätte von drei Toro-Königen", "Bewahrt königliche Reliquien", "Ruhiger und gepflegter Ort"],
      hu: ["Három Toro-király sírhelye", "Királyi ereklyéket őriznek itt", "Nyugodt és gondozott hely"],
      ro: ["Loc de înmormântare a trei regi Toro", "Păstrează relicve regale", "Loc liniștit și bine întreținut"],
      en: ["Burial site of three Toro Kings", "Preserves royal relics", "Quiet and well-maintained place"],
      es: ["Lugar de enterramiento de tres reyes de Toro", "Conserva reliquias reales", "Lugar tranquilo y bien cuidado"],
      pt: ["Local de sepultamento de três reis de Toro", "Preserva relíquias reais", "Local tranquilo e bem cuidado"],
      fr: ["Lieu de sépulture de trois rois du Toro", "Préserve des reliques royales", "Lieu calme et bien entretenu"],
    }, image: "/poi-images/karambi-royal-tombs-history-v2.webp",
    descriptionAdvanced: {
      de: "Die Karambi-Königsgräber befinden sich in der Nähe von Fort Portal und dienen als letzte Ruhestätte der Herrscher des Toro-Königreichs. Hier sind drei der ehemaligen Könige, bekannt als Omukamas, begraben: Kyebambe IV, Rukidi III und Kaboyo Olimi VII. Die Stätte ist weit mehr als nur ein Friedhof; sie ist ein spirituelles Zentrum, in dem königliche Reliquien wie traditionelle Trommeln, Speere und andere Insignien der Macht sorgfältig für die Nachwelt aufbewahrt werden. Die Gräber liegen in einer ruhigen, parkähnlichen Anlage, die von den Einheimischen mit großem Respekt und Hingabe gepflegt wird. Für Besucher bietet Karambi einen tiefen Einblick in die komplexen Traditionen und die Geschichte der Toro-Monarchie, die bis heute eine prägende kulturelle Rolle in Westuganda spielt. Die schlichte, würdevolle Architektur der Grabbauten lädt zur Reflexion über die reiche Vergangenheit der Region und die Bedeutung der Ahnenverehrung ein.",
      hu: "A Fort Portal közelében fekvő Karambi királyi sírok a Toro Királyság uralkodóinak, az omukamáknak a végső nyughelye. Itt temették el a királyság három legjelentősebb modern kori vezetőjét: IV. Kyebambét, III. Rukidit és VII. Kaboyo Olimit. A helyszín szentnek számít, és a sírok mellett számos értékes királyi ereklyét, például ceremoniális dobokat, lándzsákat és egyéb hatalmi jelképeket őriznek itt, amelyek az uralkodói méltóságot jelképezik. A sírok egy csendes, gondozott domboldalon találhatók, ahonnan békés kilátás nyílik a környező tájra. Karambi látogatása egyedülálló lehetőséget nyújt a Toro-kultúra és a helyi királyi hagyományok mélyebb megismerésére, amelyek a mai napig meghatározóak Uganda nyugati részén. A helyiek nagy becsben tartják ezt az örökséget, és a sírok fenntartása a közösség folyamatos tiszteletének jele azon őseik iránt, akik megalapozták a királyság modern történelmét.",
      ro: "Mormintele regale din Karambi, situate în apropierea orașului Fort Portal, reprezintă locul de odihnă veșnică al monarhilor (Omukama) din Regatul Toro. Acest sit de o importanță istorică deosebită găzduiește mormintele a trei regi marcanți: Kyebambe al IV-lea, Rukidi al III-lea și Kaboyo Olimi al VII-lea. Dincolo de funcția sa funerară, Karambi este un sanctuar cultural unde sunt păstrate cu sfințenie relicve regale prețioase, precum tobe ceremoniale, lănci și alte însemne ale autorității Toro. Amplasate pe un deal liniștit și meticulos întreținut, mormintele oferă o atmosferă de reverență și introspecție asupra trecutului Ugandei. Vizitatorii pot descoperi istoria fascinantă a monarhiei Toro și tradițiile care continuă să influențeze structura socială și identitatea culturală din Uganda de Vest. Simplitatea construcțiilor contrastează cu greutatea lor simbolică, transformând Karambi într-un punct de referință fundamental pentru patrimoniul african.",
      en: "The Karambi Royal Tombs, situated on the outskirts of Fort Portal, are the final resting place of the Omukamas (Kings) of the Toro Kingdom. This sacred site houses the remains of three distinguished monarchs: Kyebambe IV, Rukidi III, and Kaboyo Olimi VII. The tombs are much more than a burial ground; they serve as a cultural repository for royal regalia, including ceremonial drums, spears, and other artifacts that symbolize the power and heritage of the Toro people. Set within a peaceful, well-manicured compound, the site provides a serene atmosphere for visitors to learn about the intricate customs and historical narratives of one of Uganda's traditional kingdoms. Understanding the legacy of these kings offers vital insights into the region's cultural and political evolution. The local community maintains the site with great dignity, ensuring that the spirits and stories of their former leaders are honored and preserved for future generations.",
      es: "Las Tumbas Reales de Karambi en Uganda, cerca de Fort Portal, son el lugar de enterramiento de los gobernantes del Reino de Toro. El sitio contiene las tumbas del Omukama (Rey) Kyebambe y otros miembros de la familia real. Las tumbas se encuentran en chozas circulares tradicionales. Karambi es un importante lugar cultural y espiritual para el pueblo Batooro. El complejo está rodeado de jardines bien cuidados. Las tumbas fueron renovadas en 2008. Son parte del patrimonio cultural de Uganda y atraen visitantes.",
      pt: "Os Túmulos Reais de Karambi em Uganda, perto de Fort Portal, são o local de sepultamento dos governantes do Reino de Toro. O local contém os túmulos do Omukama (Rei) Kyebambe e outros membros da família real. Os túmulos estão alojados em cabanas circulares tradicionais. Karambi é um importante local cultural e espiritual para o povo Batooro. O complexo é cercado por jardins bem cuidados. Os túmulos foram renovados em 2008. Eles fazem parte do patrimônio cultural de Uganda e atraem visitantes.",
      fr: "Les tombeaux royaux de Karambi en Ouganda, près de Fort Portal, sont le lieu de sépulture des souverains du royaume du Toro. Le site contient les tombes de l'Omukama (roi) Kyebambe et d'autres membres de la famille royale. Les tombes sont abritées dans des huttes circulaires traditionnelles. Karambi est un lieu culturel et spirituel important pour le peuple Batooro. Le complexe est entouré de jardins bien entretenus. Les tombeaux ont été rénovés en 2008. Ils font partie du patrimoine culturel de l'Ouganda et attirent les visiteurs.",
    },
