      es: "Fort Lugard fue una fortaleza construida por el administrador colonial británico, el capitán Frederick Lugard, en Kampala.",
      pt: "Fort Lugard foi uma fortaleza construída pelo administrador colonial britânico, capitão Frederick Lugard, em Kampala.",
      fr: "Fort Lugard était une forteresse construite par l'administrateur colonial britannique, le capitaine Frederick Lugard, à Kampala.",
