      fr: ["Diamètre jusqu'à 10 mètres", "Profondeur jusqu'à 15 mètres", "Nombre de fosses: 7", "Légende depuis le XVe siècle", "Découvertes archéologiques de l'âge du fer", "Patrimoine culturel protégé depuis 1962"],
