      fr: ["Construit entre le XIIe et le XVe siècle", "Superficie : 20 hectares", "Hauteur des remparts : jusqu'à 6 mètres", "Longueur des fossés : 2 km", "Fouilles depuis 1985", "Proposition de patrimoine mondial de l'UNESCO en 1995"],
